import {
  chmodSync,
  copyFileSync,
  existsSync,
  lstatSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
} from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { readCoreVersion, readJson } from "./core-package.mjs";

// Only these directories and LICENSE are generated by this command.
const directories = [
  { source: "native/cpp", destination: "cpp/core", legacyDestination: "cpp" },
  { source: "native/apple", destination: "ios/core", legacyDestination: "ios" },
  { source: "native/android/src", destination: "android/core", legacyDestination: "android/src" },
];
const sourceExtensions = new Set([
  ".h",
  ".hpp",
  ".c",
  ".cc",
  ".cpp",
  ".m",
  ".mm",
  ".swift",
  ".kt",
  ".java",
  ".xml",
]);

function sourceFiles(directory, prefix = "") {
  const files = [];
  for (const name of readdirSync(directory).sort()) {
    const file = path.join(directory, name);
    const relative = path.join(prefix, name);
    const stat = lstatSync(file);
    if (stat.isSymbolicLink())
      throw new Error(`Shared source must not be a symlink: ${file}`);
    if (stat.isDirectory()) files.push(...sourceFiles(file, relative));
    else if (stat.isFile() && sourceExtensions.has(path.extname(name)))
      files.push(relative);
  }
  return files;
}

function allFiles(directory, prefix = "") {
  if (!existsSync(directory)) return [];
  return readdirSync(directory)
    .sort()
    .flatMap((name) => {
      const file = path.join(directory, name);
      const relative = path.join(prefix, name);
      return lstatSync(file).isDirectory()
        ? allFiles(file, relative)
        : [relative];
    });
}

export function syncCore(root, { check = false } = {}) {
  const { corePath, wrapperPath, version } = readCoreVersion(root);
  const wrapper = readJson(wrapperPath);
  if (
    wrapper.version !== version ||
    wrapper.dependencies?.["nitro-core"] !== version
  ) {
    throw new Error(
      `The RN package must pin nitro-core ${version} exactly. Run bun version:set to align workspace versions.`,
    );
  }
  const destination = path.dirname(wrapperPath);
  // Read and validate every input before removing any generated output.
  const mappings = directories.map((mapping) => {
    const files = sourceFiles(path.join(corePath, mapping.source));
    if (files.length === 0)
      throw new Error(`Missing shared sources: ${mapping.source}`);
    return { ...mapping, files };
  });
  const license = path.join(corePath, "LICENSE");
  if (!lstatSync(license).isFile())
    throw new Error("Core LICENSE must be a regular file.");
  const copies = mappings.flatMap(({ source, destination: target, files }) =>
    files.map((file) => ({
      source: path.join(corePath, source, file),
      destination: path.join(destination, target, file),
    })),
  );
  copies.push({
    source: license,
    destination: path.join(destination, "LICENSE"),
  });

  // Before the split these files were generated beside the RN adapters. Remove
  // those old copies as well, or existing checkouts compile Core twice.
  const legacyCopies = mappings.flatMap(({ legacyDestination, files }) =>
    files.map((file) => path.join(destination, legacyDestination, file)),
  ).filter((file) => existsSync(file));

  if (check) {
    if (legacyCopies.length > 0)
      throw new Error("Legacy staged Core files remain. Run bun sync-core.");
    for (const { destination: target, files } of mappings) {
      if (
        JSON.stringify(allFiles(path.join(destination, target)).sort()) !==
        JSON.stringify([...files].sort())
      ) {
        throw new Error(`Staged ${target} files are stale. Run bun sync-core.`);
      }
    }
    for (const file of copies) {
      if (
        !existsSync(file.destination) ||
        !lstatSync(file.destination).isFile() ||
        !readFileSync(file.source).equals(readFileSync(file.destination))
      ) {
        throw new Error(
          `Staged source differs from nitro-core ${version}: ${file.destination}`,
        );
      }
    }
  } else {
    for (const file of legacyCopies) rmSync(file);
    for (const mapping of mappings)
      rmSync(path.join(destination, mapping.destination), {
        recursive: true,
        force: true,
      });
    for (const file of copies) {
      mkdirSync(path.dirname(file.destination), { recursive: true });
      copyFileSync(file.source, file.destination);
      chmodSync(file.destination, lstatSync(file.source).mode & 0o777);
    }
  }
  return { version, files: copies.length };
}

if (
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  const root = fileURLToPath(new URL("../", import.meta.url));
  const check =
    process.argv.includes("--check") || process.argv.includes("--check-clean");
  const { version, files } = syncCore(root, { check });
  console.log(
    `${check ? "Verified" : "Staged"} ${files} native files from workspace nitro-core ${version}.`,
  );
}
